const __pageData = JSON.parse('{"title":"Sovereign Alliance","description":"","frontmatter":{"title":"Sovereign Alliance","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"concept","tags":["geopolitics","fifth-generation-warfare","badlands-media"],"sources":["raw/badlands-blitz-episode-11.md","raw/badlands-blitz-episode-3.md","raw/badlands-blitz-episode-7.md","raw/badlands-brief-174.md","raw/badlands-brief-2b2.md","raw/badlands-brief-414.md","raw/badlands-brief-311.md","raw/badlands-brief-314.md","raw/badlands-brief-5a2.md","raw/badlands-brief-618.md","raw/badlands-brief-625.md","raw/badlands-brief-739.md","raw/badlands-brief-95a.md","raw/badlands-brief-98d.md","raw/badlands-brief-990.md","raw/badlands-brief-9f2.md","raw/badlands-brief-9ea.md","raw/badlands-brief-774.md","raw/badlands-brief-ac2.md","raw/badlands-brief-a20.md","raw/badlands-brief-bce.md","raw/badlands-brief-bb1.md","raw/badlands-brief-ea5.md","raw/badlands-brief-f62.md","raw/badlands-brief-f02.md","raw/badlands-news-brief-048.md","raw/badlands-news-brief-125.md","raw/badlands-news-brief-168.md","raw/badlands-news-brief-1ed.md","raw/badlands-news-brief-27c.md","raw/badlands-news-brief-2d5.md","raw/badlands-news-brief-3bc.md","raw/badlands-news-brief-4c5.md","raw/badlands-news-brief-520.md","raw/badlands-news-brief-528.md","raw/badlands-news-brief-5b2.md","raw/badlands-news-brief-6e6.md","raw/badlands-news-brief-7a5.md","raw/badlands-news-brief-907.md"],"confidence":"medium"},"headers":[],"relativePath":"concepts/sovereign-alliance.md","filePath":"concepts/sovereign-alliance.md","lastUpdated":null}');
